import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor weight,
                              c10::optional<torch::Tensor> bias,
                              int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Compile-time tile parameters chosen for this specific model
// (C_in=3, K=11, stride=4, padding=2, C_out=96)
#define OH_TILE 8
#define OW_TILE 8
#define OC_TILE 16

__global__ void conv2d_tiled_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int C_in, int H, int Win,
    int C_out, int K,
    int stride, int padding,
    int OH, int OW,
    int IH_TILE, int IW_TILE)
{
    extern __shared__ float smem[];
    float* sW_ptr = smem;
    float* sX_ptr = smem + (OC_TILE * C_in * K * K);

    // Shared memory tensors via CuTe (runtime shapes/strides)
    auto sW = make_tensor(make_smem_ptr(sW_ptr),
                           make_shape(OC_TILE, C_in, K, K),
                           make_stride(C_in * K * K, K * K, K, 1));
    auto sX = make_tensor(make_smem_ptr(sX_ptr),
                           make_shape(C_in, IH_TILE, IW_TILE),
                           make_stride(IH_TILE * IW_TILE, IW_TILE, 1));

    int oc_tiles = (C_out + OC_TILE - 1) / OC_TILE;

    int ow_tile_idx = blockIdx.x;
    int oh_tile_idx = blockIdx.y;
    int n = blockIdx.z / oc_tiles;
    int oc_tile_idx = blockIdx.z % oc_tiles;

    int oc_base = oc_tile_idx * OC_TILE;
    int oh_base = oh_tile_idx * OH_TILE;
    int ow_base = ow_tile_idx * OW_TILE;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y;

    // Global tensors for this batch element
    const float* Xn = X + (int64_t)n * C_in * H * Win;
    float* Yn = Y + (int64_t)n * C_out * OH * OW;

    auto mX = make_tensor(make_gmem_ptr(Xn),
                           make_shape(C_in, H, Win),
                           make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));
    auto mW = make_tensor(make_gmem_ptr(W),
                           make_shape(C_out, C_in, K, K),
                           make_stride((int64_t)C_in * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));
    auto mY = make_tensor(make_gmem_ptr(Yn),
                           make_shape(C_out, OH, OW),
                           make_stride((int64_t)OH * OW, (int64_t)OW, (int64_t)1));

    // Load weight tile into shared memory
    int total_w = OC_TILE * C_in * K * K;
    for (int idx = tid; idx < total_w; idx += nthreads) {
        int kw = idx % K;
        int tmp = idx / K;
        int kh = tmp % K;
        tmp /= K;
        int ic = tmp % C_in;
        int oc_local = tmp / C_in;
        int oc = oc_base + oc_local;

        float val = 0.0f;
        if (oc < C_out) {
            val = mW(oc, ic, kh, kw);
        }
        sW(oc_local, ic, kh, kw) = val;
    }

    // Load input tile into shared memory (zero-padded)
    int total_x = C_in * IH_TILE * IW_TILE;
    int ih_origin = oh_base * stride - padding;
    int iw_origin = ow_base * stride - padding;

    for (int idx = tid; idx < total_x; idx += nthreads) {
        int iw_l = idx % IW_TILE;
        int tmp = idx / IW_TILE;
        int ih_l = tmp % IH_TILE;
        int ic = tmp / IH_TILE;

        int ih = ih_origin + ih_l;
        int iw = iw_origin + iw_l;

        float val = 0.0f;
        if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
            val = mX(ic, ih, iw);
        }
        sX(ic, ih_l, iw_l) = val;
    }

    __syncthreads();

    int oh_local = threadIdx.y;
    int ow_local = threadIdx.x;
    int oh = oh_base + oh_local;
    int ow = ow_base + ow_local;

    if (oh < OH && ow < OW) {
        #pragma unroll
        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
            int oc = oc_base + oc_local;
            if (oc >= C_out) continue;

            float acc = (Bias != nullptr) ? Bias[oc] : 0.0f;

            for (int ic = 0; ic < C_in; ++ic) {
                for (int kh = 0; kh < K; ++kh) {
                    int ih_l = oh_local * stride + kh;
                    for (int kw = 0; kw < K; ++kw) {
                        int iw_l = ow_local * stride + kw;
                        acc += sX(ic, ih_l, iw_l) * sW(oc_local, ic, kh, kw);
                    }
                }
            }
            mY(oc, oh, ow) = acc;
        }
    }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor weight,
                              c10::optional<torch::Tensor> bias,
                              int stride, int padding) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
    TORCH_CHECK(weight.dim() == 4, "weight must be [C_out, C_in, K, K]");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int N = (int)x_c.size(0);
    int C_in = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int Win = (int)x_c.size(3);

    int C_out = (int)w_c.size(0);
    TORCH_CHECK((int)w_c.size(1) == C_in, "weight in_channels mismatch");
    int K = (int)w_c.size(2);
    TORCH_CHECK((int)w_c.size(3) == K, "kernel must be square for this kernel");

    TORCH_CHECK(stride > 0, "stride must be > 0");
    TORCH_CHECK(padding >= 0, "padding must be >= 0");

    int OH = (H + 2 * padding - K) / stride + 1;
    int OW = (Win + 2 * padding - K) / stride + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "Invalid output size computed");

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C_out, "bias must be [C_out]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, C_out, OH, OW}, x.options());

    int IH_TILE = (OH_TILE - 1) * stride + K;
    int IW_TILE = (OW_TILE - 1) * stride + K;

    size_t smem_bytes = (size_t)(OC_TILE * C_in * K * K + C_in * IH_TILE * IW_TILE) * sizeof(float);

    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_tiled_kernel,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);
    }

    int oc_tiles = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 block(OW_TILE, OH_TILE);
    dim3 grid((OW + OW_TILE - 1) / OW_TILE,
               (OH + OH_TILE - 1) / OH_TILE,
               N * oc_tiles);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv2d_tiled_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        N, C_in, H, Win,
        C_out, K,
        stride, padding,
        OH, OW,
        IH_TILE, IW_TILE
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_tiled_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            self.stride,
            self.padding,
        )

